describe('Modal Content Independent Scrolling', () => {
  beforeEach(() => {
    cy.visit('/modal-page');
  });

  it('should scroll modal content independently when it overflows', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal has scrollable content
    cy.get('[data-testid="modal-content"]').should('have.height', 'auto');

    // Verify modal has scrollbar
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-y', 'scroll');

    // Verify modal has scroll position
    cy.get('[data-testid="modal-content"]').should('have.css', 'scroll-top', '0px');

    // Verify modal has scrollbar width
    cy.get('[data-testid="modal-content"]').should('have.css', 'scrollbar-width', 'auto');

    // Scroll modal content down
    cy.get('[data-testid="modal-content"]').scrollTo('bottom');

    // Verify scroll position has changed
    cy.get('[data-testid="modal-content"]').should('have.css', 'scroll-top', 'auto');

    // Verify modal content is now visible at bottom
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify modal background is not scrolled
    cy.get('[data-testid="modal-backdrop"]').should('have.css', 'transform', 'none');

    // Verify modal backdrop is still visible
    cy.get('[data-testid="modal-backdrop"]').should('be.visible');

    // Close modal
    cy.get('[data-testid="close-modal-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should not scroll modal backdrop when modal content overflows', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify modal backdrop is visible
    cy.get('[data-testid="modal-backdrop"]').should('be.visible');

    // Scroll modal content to bottom
    cy.get('[data-testid="modal-content"]').scrollTo('bottom');

    // Verify modal backdrop scroll position is 0
    cy.get('[data-testid="modal-backdrop"]').should('have.css', 'transform', 'none');

    // Verify modal backdrop is not scrolled
    cy.get('[data-testid="modal-backdrop"]').should('have.css', 'scroll-top', '0px');

    // Verify modal content is still scrollable
    cy.get('[data-testid="modal-content"]').should('have.css', 'overflow-y', 'scroll');

    // Verify modal content is still visible at bottom
    cy.get('[data-testid="modal-content"]').should('be.visible');

    // Verify modal backdrop is still in viewport
    cy.get('[data-testid="modal-backdrop"]').should('be.visible');

    // Close modal
    cy.get('[data-testid="close-modal-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });
});
